insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, sort) values
  ('l-ginger-turkey-noodle-soup', 'Ginger Turkey Noodle Soup', 'Light broth with turkey, noodles, mushrooms and spinach', 'lunch', 'turkey', '🍲', 20, 'quick', 423, 38, 47, 10, 5, 5, 836, '[{"name":"turkey","amount":110,"unit":"g"},{"name":"noodles","amount":50,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"soy sauce","amount":12,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","1 tbsp grated ginger"]'::jsonb, '["Slice the turkey thinly and brown it in the oil in a pot for 3 minutes with the chopped garlic and ginger","Add the water, stock cube, sliced carrots and mushrooms and simmer for 6 minutes","Add the noodles and cook for 4 minutes until soft","Stir in the spinach and soy sauce and serve as soon as the spinach wilts"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","light","turkey","noodles","mushrooms","carrots","spinach","soy sauce","garlic","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 150),
  ('l-spicy-tofu-fried-rice', 'Spicy Tofu Fried Rice', 'Fried rice with golden tofu, peas, peppers and chili', 'lunch', 'tofu', '🌶️', 20, 'quick', 611, 32, 75, 22, 9, 7, 936, '[{"name":"tofu","amount":130,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1 tsp grated ginger"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it steam dry","Cut the tofu into small cubes and fry in the oil over high heat for 5 minutes until golden","Add the diced carrots and peppers, the peas, ginger and chili flakes and stir-fry for 3 minutes","Add the rice and soy sauce and fry for 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","quick","tofu","rice","peas","carrots","peppers","soy sauce","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 151),
  ('l-spicy-tuna-rice-bowl', 'Spicy Tuna Rice Bowl', 'Rice bowl with tuna, avocado, cucumber and a spicy soy dressing', 'lunch', 'tuna', '🐟', 15, 'quick', 599, 29, 75, 22, 12, 4, 839, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"rice","amount":70,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["1 tsp sriracha or other chili sauce","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes, drain and let it cool slightly","Mix the drained tuna with the soy sauce, chili sauce and lime juice","Dice the avocado and cucumber and grate the carrots","Fill a bowl with the rice and arrange the tuna, avocado, cucumber and carrots on top"]'::jsonb, '["stovetop"]'::jsonb, '["asian","spicy","fresh","quick","tuna","rice","avocado","cucumber","carrots","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 152),
  ('l-chicken-fajita-wraps', 'Chicken Fajita Wraps', 'Spiced chicken, peppers and onion in warm tortillas', 'lunch', 'chicken', '🌯', 20, 'quick', 640, 41, 70, 21, 7, 11, 948, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"peppers","amount":100,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Slice the chicken, peppers and onion into strips and toss the chicken with the cumin, paprika and salt","Fry the chicken in the oil over high heat for 5 minutes until browned and cooked through","Add the peppers and onion and cook for 4 minutes until soft with charred edges","Warm the tortillas in a dry pan, fill them and finish with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","chicken","tortilla","peppers","onion","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 153),
  ('l-bean-cheese-quesadilla', 'Bean and Cheese Quesadilla', 'Crisp tortilla filled with kidney beans, corn and melted cheese', 'lunch', 'kidney beans', '🧀', 12, 'quick', 675, 29, 91, 22, 11, 13, 1528, '[{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"cheese","amount":40,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","pinch of salt"]'::jsonb, '["Roughly mash the drained kidney beans with the cumin and salt, then stir in the corn","Spread the beans over one tortilla, scatter over the grated cheese and top with the second tortilla","Cook in a dry pan over medium heat for 2 to 3 minutes per side until crisp and the cheese has melted","Cut into wedges and serve with the diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","tortilla","kidney beans","cheese","corn","tomato","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 154),
  ('l-chicken-burrito-bowl', 'Chicken Burrito Bowl', 'Rice bowl with spiced chicken, beans, corn, tomato and lettuce', 'lunch', 'chicken', '🥗', 20, 'quick', 573, 42, 77, 11, 8, 8, 356, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the chicken into small pieces, coat with the cumin, paprika and salt and fry in the oil for 6 minutes until cooked through","Warm the drained kidney beans and corn in the same pan for 1 minute","Fill a bowl with the rice, chicken, beans and corn, top with diced tomato and shredded lettuce and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","chicken","rice","kidney beans","corn","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 155),
  ('l-beef-tacos', 'Beef Tacos', 'Spiced beef mince in soft tortillas with lettuce, tomato and cheese', 'lunch', 'beef mince', '🌮', 20, 'quick', 730, 39, 67, 33, 7, 9, 1135, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"onion","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Brown the beef mince with the diced onion in a dry pan over high heat for 6 minutes","Stir in the cumin, paprika, chili flakes, salt and a splash of water and cook for 2 more minutes","Warm the tortillas in a dry pan","Fill them with the beef, shredded lettuce, diced tomato and grated cheese"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","beef mince","tortilla","lettuce","tomato","cheese","onion","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 156),
  ('l-sweet-potato-bean-burrito', 'Sweet Potato and Bean Burrito', 'Burrito filled with spiced sweet potato, kidney beans and corn', 'lunch', 'kidney beans', '🍠', 25, 'balanced', 534, 16, 87, 15, 13, 14, 837, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"sweet potato","amount":150,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes","Fry it in the oil over medium heat for 12 minutes, turning now and then, until tender and browned","Add the drained kidney beans, corn, cumin, paprika and salt and cook for 2 minutes, lightly crushing some of the beans","Warm the tortilla, pile the filling down the middle, add lime juice, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","light","tortilla","sweet potato","kidney beans","corn","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 157),
  ('l-shrimp-avocado-tacos', 'Shrimp and Avocado Tacos', 'Chili-lime shrimp in tortillas with avocado, tomato and lettuce', 'lunch', 'shrimp', '🍤', 15, 'quick', 767, 40, 76, 36, 15, 8, 1055, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":80,"unit":"g"},{"name":"lettuce","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","squeeze of lime juice","salt"]'::jsonb, '["Toss the shrimp with the chili flakes, cumin and salt and fry in the oil over high heat for 2 to 3 minutes until pink","Mash the avocado with lime juice and a pinch of salt","Warm the tortillas in a dry pan and spread them with the avocado","Top with the shrimp, diced tomato and shredded lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","fresh","quick","hearty","shrimp","tortilla","avocado","tomato","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 158),
  ('l-chicken-tortilla-soup', 'Chicken Tortilla Soup', 'Tomato broth with chicken, beans and corn, topped with crisp tortilla strips', 'lunch', 'chicken', '🍲', 25, 'balanced', 534, 40, 62, 15, 11, 14, 989, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp chili flakes","1 stock cube","{300} ml water","squeeze of lime juice"]'::jsonb, '["Cut the tortilla into thin strips and toast them in a dry pot over medium heat for 3 minutes until crisp, then set aside","Soften the diced onion in the oil for 3 minutes, then add the cumin and chili flakes","Add the chopped tomatoes, water, stock cube and the chicken in small pieces and simmer for 12 minutes","Stir in the drained kidney beans and corn, heat for 2 minutes, add lime juice and serve topped with the tortilla strips"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","chicken","chopped tomatoes","corn","kidney beans","onion","tortilla","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 159),
  ('l-smoky-bean-chili', 'Smoky Bean Chili', 'Kidney bean and vegetable chili with rice', 'lunch', 'kidney beans', '🌶️', 25, 'balanced', 546, 20, 96, 11, 16, 18, 687, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"rice","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","1 tsp ground cumin","1/2 tsp chili flakes","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Dice the onion and peppers and soften them in the oil for 5 minutes, then stir in the paprika, cumin and chili flakes","Add the chopped tomatoes and drained kidney beans and simmer for 12 minutes until thick","Stir in the corn, season with salt and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","comfort","light","kidney beans","chopped tomatoes","peppers","onion","corn","rice","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 160),
  ('l-huevos-rancheros', 'Huevos Rancheros', 'Fried eggs on tortillas with beans and a spicy tomato sauce', 'lunch', 'eggs', '🍳', 20, 'quick', 726, 31, 84, 29, 11, 12, 1363, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":120,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","salt"]'::jsonb, '["Soften the diced onion in half the oil for 3 minutes, add the chili flakes and cumin, then the chopped tomatoes, and simmer for 6 minutes","Stir in the drained kidney beans and warm through","Fry the eggs in the remaining oil for 2 to 3 minutes until the whites are set","Warm the tortillas in a dry pan, spoon over the beans and sauce and top each with an egg"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","eggs","tortilla","kidney beans","chopped tomatoes","onion","oil","stovetop","lunch"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 161),
  ('l-turkey-taco-salad', 'Turkey Taco Salad', 'Spiced turkey mince over lettuce with tomato, corn, beans and avocado', 'lunch', 'turkey mince', '🥗', 15, 'quick', 607, 36, 40, 37, 17, 9, 358, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Brown the turkey mince in the oil over high heat for 6 minutes with the cumin, paprika and salt","Shred the lettuce and dice the tomato and avocado","Arrange the lettuce in a bowl and top with the turkey, tomato, corn, drained kidney beans and avocado","Squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","turkey mince","lettuce","tomato","corn","kidney beans","avocado","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 162),
  ('l-tofu-fajita-bowl', 'Tofu Fajita Bowl', 'Spiced tofu with peppers, onion and corn over rice', 'lunch', 'tofu', '🫑', 20, 'quick', 590, 33, 71, 22, 9, 9, 133, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"peppers","amount":120,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp smoked paprika","salt","squeeze of lime juice"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Cut the tofu into strips, coat with the cumin, paprika and salt and fry in the oil over medium-high heat for 5 minutes","Add the sliced peppers and onion and cook for 5 minutes until soft and lightly charred","Stir in the corn and serve over the rice with lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","tofu","rice","peppers","onion","corn","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 163),
  ('l-bean-corn-avocado-salad', 'Bean, Corn and Avocado Salad', 'No-cook salad of kidney beans, corn, peppers, tomato and avocado', 'lunch', 'kidney beans', '🥑', 10, 'quick', 547, 18, 64, 29, 22, 16, 529, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"corn","amount":80,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","squeeze of lime juice","salt","handful of fresh coriander"]'::jsonb, '["Drain and rinse the kidney beans and corn","Dice the peppers, tomato and avocado","Toss everything with the olive oil, cumin, lime juice, salt and coriander"]'::jsonb, '[]'::jsonb, '["mexican","fresh","quick","light","kidney beans","corn","peppers","tomato","avocado","olive oil","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 164),
  ('l-caprese-pasta-salad', 'Caprese Pasta Salad', 'Cold pasta with mozzarella, tomato, spinach and pesto', 'lunch', 'mozzarella', '🍅', 15, 'quick', 577, 26, 66, 23, 5, 6, 527, '[{"name":"pasta","amount":75,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"spinach","amount":30,"unit":"g"}]'::jsonb, '["black pepper","pinch of salt"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, drain and rinse under cold water","Dice the tomato and tear the mozzarella into pieces","Toss the pasta with the pesto, tomato, mozzarella and spinach and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","pasta","mozzarella","tomato","pesto","spinach","stovetop","lunch"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, 165),
  ('l-tuna-pasta-salad', 'Tuna Pasta Salad', 'Pasta salad with tuna, corn, tomato and cucumber in a lemon olive oil dressing', 'lunch', 'tuna', '🐟', 15, 'quick', 495, 31, 66, 13, 5, 8, 360, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lemon juice","salt","black pepper","pinch of dried oregano"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, drain and rinse under cold water","Dice the tomato and cucumber","Toss the pasta with the drained tuna, corn, tomato, cucumber, olive oil, lemon juice and oregano and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","tuna","pasta","corn","tomato","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 166),
  ('l-minestrone', 'Minestrone', 'Chunky vegetable and bean soup with pasta and parmesan', 'lunch', 'kidney beans', '🥣', 30, 'balanced', 444, 19, 66, 13, 13, 16, 584, '[{"name":"kidney beans","amount":80,"unit":"g"},{"name":"pasta","amount":40,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"zucchini","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{400} ml water","1 tsp dried oregano","black pepper"]'::jsonb, '["Dice the onion, carrots and zucchini and soften them in the olive oil in a pot for 5 minutes","Add the chopped tomatoes, water, stock cube and oregano and simmer for 10 minutes","Add the pasta and drained kidney beans and cook for 8 to 10 minutes until the pasta is tender","Serve topped with the grated parmesan and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","kidney beans","pasta","carrots","zucchini","chopped tomatoes","onion","olive oil","parmesan","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 167),
  ('l-chicken-pesto-pasta', 'Chicken Pesto Pasta', 'Pasta with pan-fried chicken, pesto, spinach and tomato', 'lunch', 'chicken', '🍝', 20, 'quick', 536, 40, 59, 15, 5, 5, 351, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Cut the chicken into strips, season and fry in a non-stick pan over medium-high heat for 6 minutes until golden","Add the diced tomato and spinach and cook for 1 minute until the spinach wilts","Toss in the pasta, pesto and a splash of the pasta water"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chicken","pasta","pesto","spinach","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, 168),
  ('l-spinach-mushroom-frittata', 'Spinach and Mushroom Frittata', 'Thick Italian omelette with mushrooms, spinach and parmesan, with bread', 'lunch', 'eggs', '🍳', 20, 'quick', 497, 35, 24, 29, 5, 5, 623, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":60,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Slice the mushrooms and onion and fry them in the olive oil in a small non-stick pan for 5 minutes","Add the spinach and let it wilt","Beat the eggs with the grated parmesan, salt and pepper, pour over the vegetables and cook over low heat, covered, for 6 to 8 minutes until set","Slide onto a plate and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","eggs","spinach","mushrooms","parmesan","onion","olive oil","bread","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 169),
  ('l-pasta-e-ceci', 'Pasta e Ceci', 'Thick Italian chickpea and pasta soup with tomato and garlic', 'lunch', 'chickpeas', '🥣', 25, 'balanced', 509, 17, 80, 15, 14, 14, 501, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried rosemary","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and rosemary","Add the chopped tomatoes, water, stock cube and drained chickpeas and simmer for 8 minutes","Crush some of the chickpeas against the side of the pot to thicken the soup","Add the pasta and cook for 8 to 10 minutes, stirring, until tender, then season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","chickpeas","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 170),
  ('l-turkey-bolognese', 'Quick Turkey Bolognese', 'Lean turkey mince in a tomato sauce with pasta', 'lunch', 'turkey mince', '🍝', 25, 'balanced', 544, 35, 66, 16, 7, 9, 276, '[{"name":"turkey mince","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 4 minutes","Add the turkey mince and brown it for 5 minutes, then stir in the chopped garlic and oregano","Add the chopped tomatoes and simmer for 10 minutes","Meanwhile cook the pasta in salted boiling water, drain and toss with the sauce"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","turkey mince","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 171),
  ('l-garlic-shrimp-spaghetti', 'Garlic Chili Shrimp Spaghetti', 'Spaghetti with shrimp, garlic, chili, tomato and spinach', 'lunch', 'shrimp', '🍤', 15, 'quick', 540, 39, 65, 14, 5, 5, 198, '[{"name":"shrimp","amount":130,"unit":"g"},{"name":"pasta","amount":75,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Warm the olive oil in a pan and gently fry the sliced garlic and chili flakes for 1 minute","Add the shrimp and diced tomato and cook for 3 minutes until the shrimp are pink","Toss in the pasta, spinach and a splash of pasta water and finish with lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","spicy","quick","light","shrimp","pasta","garlic","tomato","spinach","olive oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 172),
  ('l-salmon-pesto-pasta', 'Salmon and Pea Pesto Pasta', 'Pasta with flaked salmon, peas and pesto', 'lunch', 'salmon', '🐟', 20, 'quick', 594, 34, 57, 24, 5, 5, 322, '[{"name":"salmon","amount":110,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"peas","amount":50,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the peas for the last 2 minutes, then drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side, then break it into flakes","Toss the pasta and peas with the pesto and fold in the salmon","Season with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","salmon","pasta","pesto","peas","stovetop","lunch"]'::jsonb, '["halal","kosher"]'::jsonb, 173),
  ('l-roasted-vegetable-chickpea-pasta', 'Vegetable and Chickpea Pasta', 'Pasta with zucchini, peppers and chickpeas in tomato sauce', 'lunch', 'chickpeas', '🍝', 25, 'balanced', 534, 19, 90, 13, 13, 17, 295, '[{"name":"chickpeas","amount":100,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Dice the zucchini and peppers and fry them in the olive oil over medium-high heat for 7 minutes until soft and browned","Add the drained chickpeas, tomato sauce and oregano and simmer for 5 minutes","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","light","chickpeas","pasta","zucchini","peppers","tomato sauce","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 174),
  ('l-chicken-caprese-salad', 'Chicken Caprese Salad', 'Sliced chicken with mozzarella, tomato, lettuce and pesto', 'lunch', 'chicken', '🥗', 15, 'quick', 479, 45, 10, 28, 3, 5, 511, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"pesto","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in the olive oil over medium heat for 5 to 6 minutes per side until cooked through, then slice","Slice the tomato and mozzarella and arrange them over the lettuce","Top with the chicken and spoon over the pesto"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","chicken","mozzarella","tomato","lettuce","pesto","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","halal"]'::jsonb, 175),
  ('l-greek-chicken-salad', 'Greek Chicken Salad', 'Grilled chicken over cucumber, tomato and lettuce with feta', 'lunch', 'chicken', '🥗', 15, 'quick', 396, 37, 11, 22, 3, 5, 526, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt","black pepper"]'::jsonb, '["Season the chicken with the oregano, salt and pepper and fry in half the olive oil over medium heat for 5 to 6 minutes per side, then slice","Chop the cucumber, tomato and lettuce and put them in a bowl","Top with the chicken and crumbled feta and dress with the remaining olive oil and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","chicken","feta","cucumber","tomato","lettuce","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 176),
  ('l-chickpea-couscous-salad', 'Chickpea Couscous Salad', 'Lemony couscous with chickpeas, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🍋', 10, 'quick', 544, 19, 89, 14, 15, 13, 312, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{80} ml boiling water","salt","handful of fresh parsley","1/2 tsp ground cumin"]'::jsonb, '["Put the couscous in a bowl with a pinch of salt, pour over the boiling water, cover and leave for 5 minutes, then fluff with a fork","Dice the cucumber, tomato and peppers","Mix everything with the drained chickpeas, olive oil, the juice of the lemon, cumin and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","chickpeas","couscous","cucumber","tomato","peppers","olive oil","lemon","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 177),
  ('l-chickpea-feta-wrap', 'Chickpea and Feta Wrap', 'Tortilla with crushed chickpeas, feta, cucumber, tomato and yogurt', 'lunch', 'chickpeas', '🌯', 10, 'quick', 446, 19, 60, 16, 10, 11, 1052, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"feta","amount":30,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","squeeze of lemon juice","black pepper"]'::jsonb, '["Roughly crush the drained chickpeas with a fork and mix them with the yogurt, cumin, lemon juice and pepper","Dice the cucumber and tomato and crumble the feta","Spread the chickpeas over the tortilla, top with the vegetables and feta and roll up tightly"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tortilla","chickpeas","feta","cucumber","tomato","yogurt","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 178),
  ('l-turkish-eggs', 'Turkish Eggs with Garlic Yogurt', 'Poached eggs on garlic yogurt with chili butter and bread', 'lunch', 'eggs', '🍳', 15, 'quick', 557, 36, 38, 29, 4, 9, 592, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"greek yogurt","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":10,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp paprika","salt","splash of vinegar"]'::jsonb, '["Stir the finely grated garlic and a pinch of salt into the yogurt and spread it in a shallow bowl","Poach the eggs in barely simmering water with a splash of vinegar for 3 minutes and lift them onto the yogurt","Melt the butter with the chili flakes and paprika until it foams and pour it over the eggs","Serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","eggs","greek yogurt","bread","butter","garlic","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 179),
  ('l-tuna-chickpea-salad', 'Tuna and Chickpea Salad', 'No-cook salad of tuna, chickpeas, tomato and cucumber with lemon', 'lunch', 'tuna', '🥗', 10, 'quick', 372, 29, 38, 14, 10, 11, 503, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Drain the tuna and chickpeas","Dice the tomato and cucumber and slice the onion very thinly","Toss everything with the olive oil, the juice of the lemon, salt, pepper and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tuna","chickpeas","tomato","cucumber","onion","olive oil","lemon","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 180),
  ('l-lemony-lentil-soup', 'Lemony Lentil Soup', 'Smooth-ish lentil and carrot soup with spinach and lemon', 'lunch', 'lentils', '🍋', 30, 'balanced', 419, 22, 68, 10, 15, 11, 205, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp ground cumin","1 stock cube","{450} ml water","black pepper"]'::jsonb, '["Dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and cumin","Add the rinsed lentils, chopped tomatoes, water and stock cube and simmer for 20 minutes until the lentils are soft","Stir in the spinach until wilted","Add the juice of the lemon and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","light","lentils","carrots","onion","chopped tomatoes","spinach","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 181),
  ('l-chicken-gyros-wrap', 'Chicken Gyros Wrap', 'Oregano chicken in a tortilla with yogurt, cucumber, tomato and onion', 'lunch', 'chicken', '🌯', 15, 'quick', 460, 40, 38, 16, 3, 8, 523, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"greek yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","1/2 tsp paprika","salt","squeeze of lemon juice"]'::jsonb, '["Cut the chicken into thin strips, toss with the oregano, paprika and salt and fry in the olive oil over high heat for 5 to 6 minutes","Slice the cucumber, tomato and onion","Warm the tortilla, spread it with the yogurt and fill with the chicken and vegetables","Squeeze over lemon juice and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","chicken","tortilla","greek yogurt","cucumber","tomato","onion","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 182),
  ('l-salmon-couscous-bowl', 'Salmon Couscous Bowl', 'Flaked salmon over lemon couscous with cucumber, tomato and spinach', 'lunch', 'salmon', '🐟', 15, 'quick', 533, 34, 51, 22, 6, 5, 106, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"couscous","amount":50,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"spinach","amount":30,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{70} ml boiling water","salt","black pepper"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Dice the cucumber and tomato","Serve the couscous on the spinach with the vegetables and salmon, with the juice of the lemon squeezed over"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","salmon","couscous","cucumber","tomato","spinach","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 183),
  ('l-quinoa-greek-salad', 'Quinoa Greek Salad', 'Quinoa with chickpeas, feta, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🥗', 20, 'quick', 531, 21, 65, 22, 11, 9, 616, '[{"name":"quinoa","amount":60,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, then drain and let it cool a little","Dice the cucumber, tomato and peppers","Toss the quinoa with the vegetables, drained chickpeas, olive oil, oregano and lemon juice","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","quinoa","chickpeas","feta","cucumber","tomato","peppers","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 184),
  ('l-spanish-omelette', 'Spanish Potato Omelette', 'Thick omelette of potato and onion cooked in olive oil', 'lunch', 'eggs', '🥔', 30, 'balanced', 520, 25, 42, 28, 5, 5, 249, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into thin slices and slice the onion","Cook them gently in the olive oil in a small non-stick pan, covered, for 12 to 15 minutes until soft but not browned","Beat the eggs with salt and pepper, stir in the potatoes and onion, and pour everything back into the pan","Cook over low heat for 5 minutes, flip using a plate and cook 3 more minutes until set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","potatoes","onion","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 185),
  ('l-garlic-shrimp-couscous', 'Garlic Shrimp with Zucchini Couscous', 'Chili-garlic shrimp over couscous with zucchini and lemon', 'lunch', 'shrimp', '🍤', 15, 'quick', 489, 39, 60, 12, 6, 5, 186, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1/2 tsp chili flakes","{80} ml boiling water","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Dice the zucchini and fry it in the olive oil over high heat for 4 minutes","Add the shrimp, sliced garlic and chili flakes and cook for 2 to 3 minutes until the shrimp are pink","Serve over the couscous with the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","shrimp","couscous","zucchini","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, 186),
  ('l-beef-kofta-wrap', 'Beef Kofta Wrap', 'Spiced beef kofta in a tortilla with yogurt, cucumber, tomato and lettuce', 'lunch', 'beef mince', '🌯', 20, 'quick', 497, 30, 37, 25, 4, 8, 550, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Mix the beef mince with the cumin, paprika, chili flakes and salt and shape it into {3} short sausages","Fry them in a dry non-stick pan over medium-high heat for 8 minutes, turning, until browned and cooked through","Slice the cucumber and tomato and shred the lettuce","Warm the tortilla, spread with the yogurt, add the kofta and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","beef mince","tortilla","yogurt","cucumber","tomato","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 187),
  ('l-mediterranean-tofu-bowl', 'Mediterranean Tofu Couscous Bowl', 'Oregano tofu with zucchini, peppers and tomato over couscous', 'lunch', 'tofu', '🥙', 20, 'quick', 531, 34, 58, 21, 10, 8, 40, '[{"name":"tofu","amount":140,"unit":"g"},{"name":"couscous","amount":55,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{75} ml boiling water","squeeze of lemon juice","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes and fry in the olive oil over medium-high heat for 5 minutes until golden","Add the diced zucchini and peppers with the oregano and cook for 5 minutes","Serve over the couscous with the diced tomato and a squeeze of lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","tofu","couscous","zucchini","peppers","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 188),
  ('l-chicken-shawarma-rice-bowl', 'Chicken Shawarma Rice Bowl', 'Spiced chicken over rice with garlic yogurt, cucumber and tomato', 'lunch', 'chicken', '🍗', 25, 'balanced', 663, 46, 76, 18, 2, 6, 99, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 minutes until browned at the edges","Serve over the rice with the diced cucumber and tomato and a spoon of yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","greek yogurt","cucumber","tomato","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, 189),
  ('l-lentil-feta-salad', 'Lentil and Feta Salad', 'Warm lentils with feta, tomato, cucumber and spinach', 'lunch', 'lentils', '🥗', 30, 'balanced', 462, 26, 54, 18, 10, 6, 498, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender but still holding their shape, then drain","Dice the tomato and cucumber","Toss the warm lentils with the olive oil, vinegar, salt and pepper, then fold in the spinach, tomato and cucumber","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","lentils","feta","tomato","cucumber","spinach","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 190),
  ('l-chicken-salad-wrap', 'Chicken Salad Wrap', 'Tortilla with chicken, lettuce, tomato, cucumber and a yogurt dressing', 'lunch', 'chicken', '🌯', 15, 'quick', 379, 35, 37, 10, 4, 7, 522, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Stir the mustard and a pinch of salt into the yogurt","Shred the lettuce and slice the tomato and cucumber","Spread the yogurt over the tortilla, add the chicken and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","tortilla","lettuce","tomato","cucumber","yogurt","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 191),
  ('l-egg-salad-sandwich', 'Egg Salad Sandwich', 'Chopped egg in a mustard yogurt dressing with lettuce and cucumber', 'lunch', 'eggs', '🥪', 15, 'quick', 365, 24, 35, 14, 5, 6, 492, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the eggs for 9 minutes, cool them under cold water and peel","Chop the eggs and mix with the yogurt, mustard, salt and pepper","Pile onto one slice of bread with the lettuce and sliced cucumber and top with the second slice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","bread","yogurt","lettuce","cucumber","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 192),
  ('l-tuna-melt-toastie', 'Tuna Melt Toastie', 'Pan-toasted sandwich with tuna, corn and melted cheese', 'lunch', 'tuna', '🥪', 10, 'quick', 423, 35, 36, 16, 5, 5, 901, '[{"name":"tuna","amount":90,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"cheese","amount":30,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Mix the drained tuna with the corn and pepper","Butter one side of each slice of bread and put one slice butter side down in a pan","Top with the tuna and grated cheese and the second slice, butter side up","Toast over medium heat for 2 to 3 minutes per side until golden and the cheese has melted"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","tuna","bread","cheese","corn","butter","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 193),
  ('l-stuffed-sweet-potato-chickpeas', 'Stuffed Sweet Potato with Chickpeas', 'Baked sweet potato filled with spiced chickpeas and spinach', 'lunch', 'chickpeas', '🍠', 15, 'quick', 507, 15, 89, 12, 18, 18, 500, '[{"name":"sweet potato","amount":300,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","1/2 tsp ground cumin","salt","squeeze of lemon juice"]'::jsonb, '["Prick the sweet potato all over and microwave on high for 8 to 10 minutes, turning once, until soft","Warm the drained chickpeas in the olive oil with the paprika, cumin and salt for 3 minutes","Stir in the spinach until it wilts","Split the sweet potato, fill it with the chickpeas and finish with lemon juice"]'::jsonb, '["stovetop","microwave"]'::jsonb, '["comfort","quick","light","sweet potato","chickpeas","spinach","olive oil","stovetop","microwave","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 194),
  ('l-chicken-vegetable-soup', 'Chicken and Vegetable Soup', 'Clear soup with chicken, potato, carrot and peas', 'lunch', 'chicken', '🍲', 30, 'balanced', 407, 36, 45, 9, 8, 10, 179, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","black pepper","handful of fresh parsley"]'::jsonb, '["Dice the onion and soften it in the oil in a pot for 3 minutes","Add the diced potatoes and carrots, the water, stock cube and the whole piece of chicken and simmer for 18 minutes","Lift out the chicken, shred it with two forks and return it to the pot with the peas","Cook 2 more minutes and season with pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","potatoes","carrots","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 195),
  ('l-ham-cheese-spinach-omelette', 'Ham, Cheese and Spinach Omelette', 'Three-egg omelette with ham, cheese and spinach, with toast', 'lunch', 'eggs', '🧀', 10, 'quick', 542, 40, 20, 33, 4, 3, 1029, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt the butter in a non-stick pan, wilt the spinach for 30 seconds and pour in the eggs","When almost set, scatter the ham and cheese over one half and fold over","Cook 1 more minute and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","eggs","ham","cheese","spinach","butter","bread","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, 196),
  ('l-warm-salmon-potato-salad', 'Warm Salmon and Potato Salad', 'Flaked salmon with potatoes and green beans in a lemon yogurt dressing', 'lunch', 'salmon', '🥔', 25, 'balanced', 514, 32, 48, 23, 8, 8, 107, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Mix the yogurt with the mustard, the juice of the lemon, salt and pepper","Toss the warm potatoes and beans in the dressing and fold in the salmon"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","light","salmon","potatoes","green beans","yogurt","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, 197),
  ('l-turkey-bacon-avocado-sandwich', 'Turkey, Bacon and Avocado Sandwich', 'Toasted sandwich with turkey, crisp bacon, avocado and tomato', 'lunch', 'turkey', '🥪', 15, 'quick', 627, 39, 45, 35, 15, 6, 595, '[{"name":"turkey","amount":100,"unit":"g"},{"name":"bacon","amount":25,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 minutes until crisp and set it aside","Slice the turkey thinly, season and fry it in the bacon fat for 4 minutes until cooked through","Toast the bread and spread it with the mashed avocado","Layer on the turkey, bacon, sliced tomato and lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["quick","turkey","bacon","bread","avocado","tomato","lettuce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 198),
  ('l-chicken-quinoa-bowl', 'Chicken Quinoa Bowl', 'Quinoa with chicken, broccoli and carrot in a lemon olive oil dressing', 'lunch', 'chicken', '🥗', 20, 'quick', 519, 42, 56, 16, 10, 6, 130, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"quinoa","amount":60,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, adding the broccoli florets for the last 3, then drain","Season the chicken and fry it in half the olive oil for 5 to 6 minutes per side, then slice","Grate the carrots","Serve the quinoa and broccoli topped with the chicken and carrots, dressed with the remaining olive oil and the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chicken","quinoa","broccoli","carrots","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 199),
  ('l-beef-potato-hash', 'Beef and Potato Hash', 'Skillet of beef mince, crisp potatoes, onion and peas', 'lunch', 'beef mince', '🥔', 25, 'balanced', 580, 30, 55, 27, 8, 7, 150, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes, turning, until golden and tender","Push them aside, add the beef mince and diced onion and brown for 6 minutes","Stir in the peas, paprika, salt and pepper and cook 2 more minutes"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","beef mince","potatoes","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 200),
  ('l-pork-schnitzel-sandwich', 'Pork Schnitzel Sandwich', 'Thin breaded pork cutlet in bread with lettuce', 'lunch', 'pork', '🥪', 20, 'quick', 592, 43, 43, 27, 5, 4, 462, '[{"name":"pork","amount":120,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","1 tsp mustard","squeeze of lemon juice"]'::jsonb, '["Flatten the pork between two sheets of baking paper until about 1 cm thick and season it","Coat it in the flour, then in the beaten egg, then in the flour again","Fry in the oil over medium-high heat for 3 minutes per side until golden and cooked through","Spread the bread with mustard, add the lettuce and schnitzel and squeeze over lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","pork","bread","flour","eggs","lettuce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 201),
  ('l-tofu-scramble-wrap', 'Tofu Scramble Wrap', 'Tortilla filled with scrambled tofu, spinach, peppers and tomato', 'lunch', 'tofu', '🌯', 15, 'quick', 482, 33, 42, 23, 9, 7, 508, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"spinach","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp turmeric","1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Dice the peppers and cook them in the oil for 3 minutes","Crumble in the tofu with the turmeric, cumin, salt and pepper and cook for 5 minutes","Stir in the spinach and diced tomato until the spinach wilts","Warm the tortilla, add the scramble and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","tofu","tortilla","spinach","peppers","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 202),
  ('l-fish-finger-sandwich', 'Crispy Fish Sandwich', 'Pan-fried breaded white fish in bread with lettuce and lemon yogurt', 'lunch', 'white fish', '🐟', 20, 'quick', 554, 43, 44, 22, 5, 5, 489, '[{"name":"white fish","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"flour","amount":15,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cut the fish into thick strips, season and coat in the flour, then the beaten egg, then the flour again","Fry in the oil over medium-high heat for 2 to 3 minutes per side until golden","Stir lemon juice into the yogurt","Fill the bread with the lettuce, fish and yogurt sauce"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","white fish","bread","flour","eggs","lettuce","yogurt","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, 203),
  ('l-shrimp-avocado-salad', 'Shrimp and Avocado Salad', 'Quick salad of pan-fried shrimp, avocado, tomato and cucumber with lemon', 'lunch', 'shrimp', '🥗', 10, 'quick', 471, 34, 26, 30, 14, 7, 189, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the shrimp in half the olive oil over high heat for 2 to 3 minutes until pink and season","Dice the avocado, tomato and cucumber and tear the lettuce","Toss the salad with the remaining olive oil and the juice of the lemon and top with the shrimp"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","shrimp","avocado","lettuce","tomato","cucumber","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal"]'::jsonb, 204),
  ('l-chicken-burger', 'Chicken Burger', 'Juicy chicken mince patty in bread with cheese, lettuce and tomato', 'lunch', 'chicken mince', '🍔', 15, 'quick', 508, 39, 34, 24, 6, 5, 572, '[{"name":"chicken mince","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper","1 tsp mustard"]'::jsonb, '["Mix the chicken mince with the paprika, salt and pepper and shape into a flat patty","Fry in the oil over medium heat for 5 minutes per side until cooked through, laying the cheese on top for the last minute","Toast the bread and spread with mustard","Add the lettuce, patty and sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","chicken mince","bread","lettuce","tomato","cheese","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 205),
  ('l-turkey-vegetable-rice-skillet', 'Turkey and Vegetable Rice Skillet', 'One-pan turkey mince with rice, zucchini and peppers in tomato sauce', 'lunch', 'turkey mince', '🍚', 25, 'balanced', 531, 33, 65, 16, 5, 11, 118, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"rice","amount":60,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","{200} ml water","salt","black pepper"]'::jsonb, '["Brown the turkey mince in the oil in a lidded pan for 5 minutes","Add the diced zucchini and peppers and the paprika and cook for 3 minutes","Stir in the rice, tomato sauce, water and salt, cover and simmer on low heat for 15 minutes until the rice is tender","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["light","turkey mince","rice","zucchini","peppers","tomato sauce","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 206),
  ('l-meatball-sandwich', 'Meatball Sandwich', 'Meatballs in tomato sauce with melted cheese in bread', 'lunch', 'mixed mince', '🥪', 20, 'quick', 541, 34, 38, 28, 6, 7, 572, '[{"name":"mixed mince","amount":110,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato sauce","amount":80,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"}]'::jsonb, '["1/2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Season the mixed mince with the oregano, salt and pepper and roll it into {5} small balls","Fry them in a dry non-stick pan for 6 minutes, turning, until browned","Add the tomato sauce and simmer for 5 minutes until the meatballs are cooked through","Spoon onto the bread, top with the grated cheese and close the sandwich"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","mixed mince","bread","tomato sauce","cheese","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, 207),
  ('l-egg-potato-green-bean-salad', 'Egg, Potato and Green Bean Salad', 'Warm salad of potatoes, green beans, tomato and boiled eggs', 'lunch', 'eggs', '🥗', 20, 'quick', 445, 20, 46, 21, 8, 7, 178, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":100,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, for 15 minutes, adding the eggs for the last 8 minutes and the green beans for the last 5","Drain, cool the eggs under cold water, peel and quarter them","Whisk the olive oil with the mustard, vinegar, salt and pepper","Toss the potatoes, beans and tomato wedges in the dressing and top with the eggs"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","eggs","potatoes","green beans","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 208),
  ('l-chicken-bacon-corn-chowder', 'Chicken, Bacon and Corn Chowder', 'Creamy soup with chicken, bacon, potato and corn', 'lunch', 'chicken', '🥣', 30, 'balanced', 495, 37, 46, 18, 5, 13, 438, '[{"name":"chicken","amount":110,"unit":"g"},{"name":"bacon","amount":20,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"milk","amount":150,"unit":"ml"},{"name":"onion","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{250} ml water","black pepper"]'::jsonb, '["Fry the chopped bacon with the butter in a pot for 3 minutes, then add the diced onion for 3 minutes","Add the diced potatoes, the chicken in small pieces, the water and stock cube and simmer for 15 minutes","Stir in the corn and milk and heat gently for 3 minutes without boiling","Lightly crush some of the potatoes to thicken and season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","bacon","potatoes","corn","milk","onion","butter","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy"]'::jsonb, 209),
  ('l-chicken-avocado-rice-bowl', 'Chicken and Avocado Rice Bowl', 'Rice bowl with sliced chicken, avocado, corn and tomato', 'lunch', 'chicken', '🥑', 20, 'quick', 744, 44, 86, 26, 12, 5, 188, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"corn","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["squeeze of lime juice","salt","black pepper"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Dice the avocado and tomato","Top the rice with the chicken, avocado, corn and tomato and squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","hearty","chicken","rice","avocado","corn","tomato","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 210),
  ('l-beef-burger-wedges', 'Beef Burger with Potato Wedges', 'Cheeseburger with lettuce and tomato and oven wedges', 'lunch', 'beef mince', '🍔', 35, 'balanced', 807, 46, 68, 39, 9, 7, 597, '[{"name":"beef mince","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"},{"name":"tomato","amount":50,"unit":"g"},{"name":"oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","salt","black pepper"]'::jsonb, '["Heat the oven to 220°C, cut the potatoes into wedges, toss with the oil, paprika and salt and roast for 25 minutes, turning once","Season the beef mince, shape it into a patty and fry in a dry pan over medium-high heat for 4 minutes per side","Lay the cheese on the patty for the last minute so it melts","Serve in the bread with the lettuce and sliced tomato, with the wedges on the side"]'::jsonb, '["stovetop","oven"]'::jsonb, '["comfort","hearty","beef mince","bread","potatoes","cheese","lettuce","tomato","oil","stovetop","oven","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 211),
  ('l-steak-sandwich', 'Steak and Onion Sandwich', 'Seared beef with soft onions and cheese in toasted bread', 'lunch', 'beef', '🥩', 15, 'quick', 534, 47, 37, 22, 6, 6, 657, '[{"name":"beef","amount":140,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"onion","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"butter","amount":8,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Slice the onion and cook it in the butter over medium heat for 6 minutes until soft and golden, then push aside","Season the beef and sear it in the same pan over high heat for 2 minutes per side, rest for 2 minutes and slice thinly","Toast the bread and spread with mustard","Fill with the lettuce, beef, onions and sliced cheese"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","beef","bread","onion","cheese","butter","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 212),
  ('l-pork-apple-salad', 'Pork and Apple Salad', 'Pan-fried pork strips over lettuce with apple, cucumber and a mustard dressing', 'lunch', 'pork', '🍏', 15, 'quick', 478, 34, 45, 19, 8, 22, 235, '[{"name":"pork","amount":130,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"lettuce","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1 tsp mustard","splash of vinegar","salt","black pepper"]'::jsonb, '["Cut the pork into thin strips, season and fry in half the olive oil over high heat for 4 to 5 minutes","Slice the apple and cucumber thinly and tear the lettuce","Whisk the remaining olive oil with the mustard, vinegar, salt and pepper","Toss the salad in the dressing, top with the pork and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","pork","apple","lettuce","cucumber","olive oil","bread","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 213),
  ('l-chicken-pesto-panini', 'Chicken Pesto Panini', 'Pressed sandwich with chicken, mozzarella, tomato and pesto', 'lunch', 'chicken', '🥪', 20, 'quick', 745, 62, 51, 32, 8, 7, 1090, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Spread the pesto on the bread and layer on the chicken, sliced mozzarella and sliced tomato to make a double-decker sandwich","Toast it in the dry pan over medium heat, pressing down with a spatula, for 2 to 3 minutes per side until the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","hearty","chicken","bread","mozzarella","pesto","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, 214),
  ('l-beef-bean-burrito', 'Beef and Bean Lunch Burritos', 'Two burritos with spiced beef mince, kidney beans and cheese', 'lunch', 'beef mince', '🌯', 20, 'quick', 825, 46, 75, 37, 8, 9, 1281, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, drained kidney beans and a splash of water and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","beef mince","tortilla","kidney beans","cheese","tomato","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 215),
  ('l-salmon-avocado-rice-bowl', 'Salmon and Avocado Rice Bowl', 'Pan-fried salmon over rice with avocado, cucumber and soy', 'lunch', 'salmon', '🍣', 20, 'quick', 825, 38, 79, 40, 11, 2, 647, '[{"name":"salmon","amount":140,"unit":"g"},{"name":"rice","amount":80,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"soy sauce","amount":10,"unit":"g"}]'::jsonb, '["squeeze of lime juice","sesame seeds if you have them"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side and break into large flakes","Slice the avocado and cucumber","Top the rice with the salmon, avocado and cucumber and dress with the soy sauce and lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","fresh","quick","hearty","salmon","rice","avocado","cucumber","soy sauce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 216),
  ('l-peanut-chicken-noodles', 'Peanut Chicken Noodles', 'Warm noodles with chicken and carrot in a peanut soy sauce', 'lunch', 'chicken', '🥜', 20, 'quick', 752, 54, 76, 26, 6, 7, 1058, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"noodles","amount":90,"unit":"g"},{"name":"peanut butter","amount":25,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"soy sauce","amount":15,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["3 tbsp hot water","squeeze of lime juice"]'::jsonb, '["Cook the noodles according to the packet and drain","Slice the chicken and stir-fry it in the oil over high heat for 5 minutes with the carrots cut into thin strips","Whisk the peanut butter with the soy sauce, hot water and lime juice","Toss the noodles and sauce through the chicken and heat for 1 minute"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","hearty","chicken","noodles","peanut butter","carrots","soy sauce","oil","stovetop","lunch"]'::jsonb, '["dairy-free","halal","kosher"]'::jsonb, 217),
