  ('l-chicken-feta-chickpea-couscous', 'Chicken, Feta and Chickpea Couscous', 'Couscous with oregano chicken, chickpeas, cucumber and feta', 'lunch', 'chicken', '🥙', 20, 'quick', 798, 56, 84, 25, 10, 5, 730, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"couscous","amount":80,"unit":"g"},{"name":"chickpeas","amount":80,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["{100} ml boiling water","1 tsp dried oregano","salt","squeeze of lemon juice"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Season the chicken with the oregano and salt and fry in half the olive oil for 5 to 6 minutes per side, then slice","Mix the couscous with the drained chickpeas, diced cucumber, remaining olive oil and lemon juice","Top with the chicken and crumbled feta"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","hearty","chicken","couscous","chickpeas","feta","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, 220),
