  ('l-bacon-egg-potato-hash', 'Bacon, Egg and Potato Hash', 'Crisp potatoes with bacon and onion, topped with three fried eggs', 'lunch', 'eggs', '🥓', 25, 'balanced', 724, 34, 57, 40, 7, 5, 629, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"bacon","amount":50,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes until golden","Add the chopped bacon and diced onion with the paprika and cook for 5 minutes until the bacon is crisp","Make {n:eggs} gaps in the hash, crack in the eggs, cover and cook for 3 minutes until the whites are set","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","eggs","potatoes","bacon","onion","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, 224),
